//! Table tests of sigmastate's limit of 100,000 items on a collection. Its collection class refuses a
//! longer array in its constructor (v6.0.6 `CollsOverArrays.scala:13-14`), so no producer can return
//! one; here the array's type refuses it (`ergotree_ir::mir::coll_value::CollArray`). Six producers
//! can return more than they were given: `Append`, `Coll.flatMap`, `Coll.patch`, `Global.serialize`,
//! `SigmaPropBytes` and `SubstConstants`; `flatMap` alone can be asked for a result of any length
//! at a price that does not grow with it, so it keeps no item past the limit and still refuses in
//! sigmastate's order (`FLAT_MAP_ORDER`, `FLAT_MAP_PARTS`, `FAN_OUT`). Each row is a collection of
//! n items built from a one-item constant by sixteen doublings and a slice, handed to one of
//! them: the last count sigmastate accepts, with its value and cost, and a count it refuses, with
//! the cost counter where it stops.
//! The rows are sigma-state 6.0.7's at activated version 3; below tree version 3 its answers at
//! activated version 2 are the same (queue item 33's `measure/`, generated by
//! `measure/tests/gen_table.py`)
#![allow(clippy::unwrap_used)]

use crate::eval::reduce_to_crypto;
use crate::eval::test_util::{eval_body_at, eval_body_under, innermost};
use crate::eval::EvalError;
use crate::eval::{Env, Evaluable};
use alloc::boxed::Box;
use ergotree_ir::chain::context::Context;
use ergotree_ir::chain::context_extension::ContextExtension;
use ergotree_ir::ergo_tree::{ErgoTree, ErgoTreeVersion};
use ergotree_ir::mir::coll_value::CollLengthError;
use ergotree_ir::mir::constant::Constant;
use ergotree_ir::mir::expr::Expr;
use ergotree_ir::mir::get_var::GetVar;
use ergotree_ir::mir::value::Value;
use ergotree_ir::serialization::sigma_byte_reader::from_bytes;
use ergotree_ir::serialization::sigma_byte_reader::SigmaByteRead;
use ergotree_ir::serialization::SigmaSerializable;
use ergotree_ir::sigma_protocol::sigma_boolean::SigmaBoolean;
use ergotree_ir::types::stype::SType;
use sigma_test_util::force_any_val;

/// A row: its name in the round's row sets, the expression's bytes, the tree version, what the
/// jars answer, and the cost counter. The answer is `LEN n` (a collection of n items), `INT n`,
/// `TOOLONG n` (sigmastate's refusal of a collection of n items: `EvalError::CollLength`), or `ERR`
/// for any other error that is no cost error
type Row = (&'static str, &'static str, u8, &'static str, u64);

/// A row under a JIT cost limit: a row with the limit before its answer, which is `LIMIT` for a
/// cost error
type LimitRow = (&'static str, &'static str, u8, u64, &'static str, u64);

/// What is wrong with one row at one activated version, if anything: its outcome, its value or
/// its cost counter is not the table's
fn wrong(row: &Row, limit: Option<u64>, activated: i8) -> Option<alloc::string::String> {
    let (name, body, version, expected, cost) = *row;
    let version = ErgoTreeVersion::from(version);
    let (res, stopped_at) = match limit {
        Some(limit) => eval_body_under(body, version, activated, limit),
        None => eval_body_at(body, version, activated),
    };
    let got = match &res {
        Ok(Value::Coll(coll)) => alloc::format!("LEN {}", coll.len()),
        Ok(Value::Int(n)) => alloc::format!("INT {n}"),
        Ok(_) => "another value".into(),
        Err(e) if e.is_cost_error() => "LIMIT".into(),
        Err(e) => match innermost(e) {
            EvalError::CollLength(CollLengthError(n)) => alloc::format!("TOOLONG {n}"),
            _ => "ERR".into(),
        },
    };
    if got == expected && stopped_at == cost {
        return None;
    }
    Some(alloc::format!(
        "{name} at activated {activated}: expected {expected} at {cost}, got {got} at {stopped_at}"
    ))
}

/// Both activated versions of today's blocks. The jars refuse tree version 3 at activated version
/// 2, so those rows are left out there
fn activations(version: u8) -> &'static [i8] {
    if version == 3 {
        &[3]
    } else {
        &[2, 3]
    }
}

/// A whole tree: its name in the round's row set, the tree's bytes, the activated version, what
/// the jars' `fullReduction` answers (`TrueProp`, or `TOOLONG n`) and the reduction's block cost
type TreeRow = (&'static str, &'static str, i8, &'static str, u64);

/// The longest a length refusal's text may be on the node's path, as `Display` and as `Debug`
const SHOWN_MAX: usize = 1_000;
const DEBUGGED_MAX: usize = 5_000;

/// A context with no variable, no cost yet and no cost limit. No tree reads anything else of it
fn context(activated: i8) -> Context<'static> {
    let mut ctx = force_any_val::<Context>();
    ctx.extension = Box::leak(Box::new(ContextExtension::empty()));
    ctx.activated_script_version_byte = activated;
    ctx.jit_cost.set(0);
    ctx.jit_cost_limit = None;
    ctx
}

fn parse_tree(tree: &str, activated: i8) -> ErgoTree {
    let bytes = base16::decode(tree.as_bytes()).unwrap();
    from_bytes(&bytes)
        .with_versions(
            ErgoTreeVersion::from(activated as u8),
            ErgoTreeVersion::V3,
            ErgoTree::sigma_parse,
        )
        .unwrap()
}

/// What the fork gives for a tree on the node's path, and the cost of the reduction. The length
/// refusal is told by its text: the reduction returns its error inside a report of the source,
/// which holds the error's text and not its variant
fn reduce_row(tree: &str, activated: i8) -> (alloc::string::String, u64) {
    match reduce_to_crypto(&parse_tree(tree, activated), &context(activated)) {
        Ok(r) if r.sigma_prop == SigmaBoolean::TrivialProp(true) => ("TrueProp".into(), r.cost),
        Ok(r) => (
            alloc::format!("another proposition: {:?}", r.sigma_prop),
            r.cost,
        ),
        Err(e) => {
            let text = alloc::format!("{e}");
            match text.split_once("Cannot create collection with size ") {
                Some((_, rest)) => {
                    let n = rest.split(' ').next().unwrap_or_default();
                    (alloc::format!("TOOLONG {n}"), 0)
                }
                None => ("ERR".into(), 0),
            }
        }
    }
}

/// A constant built in memory can hold more items than any bytes can bring (a data collection's
/// count is an unsigned short): it is refused where it becomes a runtime value, with the same
/// refusal
#[test]
fn a_constant_built_in_memory_is_refused_at_evaluation() {
    let constant = |n: usize| Expr::Const(Constant::from(alloc::vec![0i8; n]));
    let ctx = force_any_val::<Context>();
    let at = constant(100_000).eval(&mut Env::empty(), &ctx);
    assert!(matches!(&at, Ok(Value::Coll(c)) if c.len() == 100_000));
    let over = constant(100_001).eval(&mut Env::empty(), &ctx);
    assert!(
        matches!(&over, Err(e) if matches!(innermost(e), EvalError::CollLength(CollLengthError(100_001))))
    );
}

/// A context variable built in memory is data like a constant: the same refusal, by its own
/// variant, where the variable becomes a value
#[test]
fn a_context_variable_built_in_memory_is_refused_at_its_read() {
    let variable = |n: usize| {
        let mut ctx = force_any_val::<Context>();
        ctx.extension = Box::leak(Box::new(ContextExtension {
            values: [(1u8, Constant::from(alloc::vec![0i8; n]).into())]
                .into_iter()
                .collect(),
        }));
        let get_var = Expr::GetVar(
            GetVar {
                var_id: 1,
                var_tpe: SType::SColl(SType::SByte.into()),
            }
            .into(),
        );
        get_var.eval(&mut Env::empty(), &ctx).map(|v| v.to_static())
    };
    assert!(matches!(variable(100_000), Ok(Value::Opt(Some(_)))));
    assert!(
        matches!(&variable(100_001), Err(e) if matches!(innermost(e), EvalError::CollLength(CollLengthError(100_001))))
    );
}

/// The refusal a node logs names the length and no value: its text is short, whatever the
/// collections the script built before it (`TREES`: `append|over|seg|v0`)
#[test]
fn the_refusal_on_the_nodes_path_is_short() {
    let tree = TREES
        .iter()
        .find(|row| row.0 == "append|over|seg|v0")
        .unwrap()
        .1;
    let e = reduce_to_crypto(&parse_tree(tree, 3), &context(3)).unwrap_err();
    assert!(!e.is_cost_error());
    let (shown, debugged) = (alloc::format!("{e}"), alloc::format!("{e:?}"));
    for text in [&shown, &debugged] {
        assert!(text.contains("Cannot create collection with size 100001 greater than 100000"));
    }
    assert!(shown.len() < SHOWN_MAX, "{}", shown.len());
    assert!(debugged.len() < DEBUGGED_MAX, "{}", debugged.len());
}

fn check(rows: &[Row]) {
    let mut wrongs = alloc::vec::Vec::new();
    for row in rows {
        for activated in activations(row.2) {
            wrongs.extend(wrong(row, None, *activated));
        }
    }
    assert!(
        wrongs.is_empty(),
        "{} runs of {} rows:\n{}",
        wrongs.len(),
        rows.len(),
        wrongs.join("\n")
    );
}

