#[test]
fn trees() {
    let mut wrongs = alloc::vec::Vec::new();
    for (name, tree, activated, expected, cost) in TREES {
        let (got, at) = reduce_row(tree, *activated);
        if got != *expected || at != *cost {
            wrongs.push(alloc::format!(
                "{name} at activated {activated}: expected {expected} @{cost}, got {got} @{at}"
            ));
        }
    }
    assert!(
        wrongs.is_empty(),
        "{} runs:\n{}",
        wrongs.len(),
        wrongs.join("\n")
    );
}

