#[test]
fn limits() {
    let mut wrongs = alloc::vec::Vec::new();
    for (name, body, version, limit, expected, cost) in LIMITS {
        let row = (*name, *body, *version, *expected, *cost);
        for activated in activations(*version) {
            wrongs.extend(wrong(&row, Some(*limit), *activated));
        }
    }
    assert!(
        wrongs.is_empty(),
        "{} runs:\n{}",
        wrongs.len(),
        wrongs.join("\n")
    );
}
